import re
for h in hypotheses:
 for field,value in list(h.items()):
  if field in {'id','source'}: continue
  for prefix in ['TikTok','Tokopedia','Enzim','X']:
   value=re.sub(r'(?<![A-Za-z])'+prefix+r'(?=\d)',prefix+' ',value)
  value=value.replace('Redditjm','Reddit jm').replace('Redditjn','Reddit jn')
  value=value.replace('Indomaret2025','Indomaret 2025').replace('SensitiveExpert100g','Sensitive Expert 100 g').replace('UltraWhite','Ultra White')
  h[field]=value
fields=list(hypotheses[0])
with (HERE/'HYPOTHESIS_MATRIX.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(hypotheses)
md=['# Competing hypothesis matrix','', '3 November 2026. This matrix records analyst assessments, not verified cause prevalence. Mechanism plausibility and applicability to confirmed 18–30 Pepsodent Premium-to-Basic switchers are separate. Sources are retained project artifacts.','']
